CREATE POLICY "Public profiles are viewable by everyone." ON "public"."profiles" FOR SELECT USING (true);



CREATE POLICY "Users can delete members if owner or removing self" ON "public"."pantry_members" FOR DELETE USING ((("auth"."uid"() = "user_id") OR "public"."is_pantry_owner"("pantry_id")));



CREATE POLICY "Users can delete pantries they own" ON "public"."pantries" FOR DELETE USING ("public"."is_pantry_owner"("id"));



