CREATE POLICY "Users can insert themselves or owner can insert members" ON "public"."pantry_members" FOR INSERT WITH CHECK ((("auth"."uid"() = "user_id") OR (("user_id" IS NULL) AND "public"."is_pantry_owner"("pantry_id"))));



CREATE POLICY "Users can update members if owner or updating self" ON "public"."pantry_members" FOR UPDATE USING ((("auth"."uid"() = "user_id") OR "public"."is_pantry_owner"("pantry_id")));



CREATE POLICY "Users can update own profile." ON "public"."profiles" FOR UPDATE USING (("auth"."uid"() = "id"));



CREATE POLICY "Users can update pantries they are owners of" ON "public"."pantries" FOR UPDATE USING ("public"."is_pantry_owner"("id"));



CREATE POLICY "Users can view members of their pantries" ON "public"."pantry_members" FOR SELECT USING ((("user_id" = "auth"."uid"()) OR "public"."is_pantry_member"("pantry_id")));



CREATE POLICY "Users can view pantries they are members of" ON "public"."pantries" FOR SELECT USING ("public"."is_pantry_member"("id"));



CREATE POLICY "Users can view pantries they created" ON "public"."pantries" FOR SELECT USING (("auth"."uid"() = "created_by"));



